package com.bank.auditord.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Enumerate all valid topological orders via in-degree backtracking.
public class AuditOrdersService {
    private static final Logger log = Logger.getLogger(AuditOrdersService.class.getName());

    public List<List<Integer>> allOrders(int taskCount, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < taskCount; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[taskCount];
        for (int[] p : prerequisites) {             // p = {prerequisite, dependent}
            adj.get(p[0]).add(p[1]);
            indeg[p[1]]++;
        }
        List<List<Integer>> results = new ArrayList<>();
        boolean[] used = new boolean[taskCount];
        build(taskCount, adj, indeg, used, new ArrayList<>(), results);
        log.info(() -> "Found " + results.size() + " valid audit orders");
        return results;
    }

    private void build(int n, List<List<Integer>> adj, int[] indeg,
                       boolean[] used, List<Integer> partial, List<List<Integer>> results) {
        if (partial.size() == n) {
            results.add(new ArrayList<>(partial)); // a complete valid order
            return;
        }
        for (int t = 0; t < n; t++) {
            if (!used[t] && indeg[t] == 0) {         // this task is currently runnable
                used[t] = true;
                for (int next : adj.get(t)) indeg[next]--;
                partial.add(t);
                build(n, adj, indeg, used, partial, results);
                partial.remove(partial.size() - 1); // undo choice
                for (int next : adj.get(t)) indeg[next]++;
                used[t] = false;
            }
        }
    }
}
