package com.bank.auditord;

import com.bank.auditord.service.AuditOrdersService;
import java.util.List;
import java.util.logging.Logger;

public class AuditOrdersApplication {
    private static final Logger log = Logger.getLogger(AuditOrdersApplication.class.getName());

    public static void main(String[] args) {
        AuditOrdersService service = new AuditOrdersService();
        // 0 before 2, 1 before 2
        int[][] prereqs = {{0, 2}, {1, 2}};
        List<List<Integer>> orders = service.allOrders(3, prereqs);
        log.info("All valid audit orders: " + orders);
    }
}
